pub(crate) fn env_stretches(
    probes: &[ProbeSummary],
    warmup: usize,
    tail_len: usize,
) -> (&[ProbeSummary], &[ProbeSummary], &[ProbeSummary]) {
    let (warm, during) = probes.split_at(warmup.min(probes.len()));
    let tail = &warm[warm.len() - tail_len.min(warm.len())..];
